import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"限流与熔断","description":"","frontmatter":{"title":"限流与熔断","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rate-limit-circuit-breaker.md","filePath":"cs/rate-limit-circuit-breaker.md","lastUpdated":1789023840000}'),h={name:"cs/rate-limit-circuit-breaker.md"};function E(_,a,m,u,B,f){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="限流与熔断" tabindex="-1">限流与熔断 <a class="header-anchor" href="#限流与熔断" aria-label="Permalink to &quot;限流与熔断&quot;">​</a></h1><div class="epigraph"><p>限流挡住过量好请求；熔断在下游已病时拒绝新请求，避免重试把病机打死。二者都是负载的负反馈，不是业务正确性。</p><footer>—— 据 Netflix Hystrix 设计；token bucket / leaky bucket 经典控制；Dean 对过载的讨论整理</footer></div><p>上一课<a href="/cs/cache-stampede-hotkey">雪崩与热键</a>仍可能打穿。缺口是<strong>保护面</strong>：即使单飞，总量仍可超过存储。本课钉限流与熔断，不重写填充租约。后课超时退避说明熔断打开期间重试如何把闭环做坏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>限流：令牌桶、漏桶、滑动窗口，按键、用户、分片配额。超限快速失败，保护的是被调用者。熔断：统计错误率或延迟，打开后短时间短路，半开探测。Nygard 的《Release It!》把熔断当稳定模式；Hystrix 做成库。</p><p>缺口：限流在调用方还是网关。只在一端，另一端仍可被别的客户端打满。熔断若按错误率，下游限流返回的 429 会被当成故障而打开——策略要区分过载与真故障。</p><p><span class="marginnote">令牌桶允许短突发；漏桶平滑。选哪一种是产品对突发的态度，不是定理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层：边缘限流（用户）+ 服务间限流（依赖配额）+ 熔断（依赖健康）。配额要按分片，避免热用户占满全局桶。熔断窗口与半开探测并发数要小，防探测雪崩。</p>',9)),(e(),n(p,null,{default:r(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20RL%7B%22%E9%99%90%E6%B5%81%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20RL%20--%3E%7C%22%E5%90%A6%22%7C%20REJ%5B%22%E5%BF%AB%E9%80%9F%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20RL%20--%3E%7C%22%E6%98%AF%22%7C%20CB%7B%22%E7%86%94%E6%96%AD%E5%85%B3%E9%97%AD%3F%22%7D%0A%20%20CB%20--%3E%7C%22%E5%BC%80%22%7C%20FAIL%5B%22%E7%9F%AD%E8%B7%AF%22%5D%0A%20%20CB%20--%3E%7C%22%E5%85%B3%22%7C%20DOWN%5B%22%E4%B8%8B%E6%B8%B8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要用熔断替代<a href="/cs/timeout-backoff">超时</a>：无限等会让错误率统计失真。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过载崩溃：队列满、GC、线程池耗尽。熔断把失败从「超时 30s」变成「立即」，释放调用方资源。这与<a href="/cs/tail-latency-hedging">尾延迟</a>相关：长尾占满池子。限流是主动掉请求保平均数；熔断是下游已掉时停止喂食。</p><p>分布式限流：中心计数器是热点；本地近似桶会超卖。超卖多少要进规格。本课不把 Redis INCR 当完备分布式桶证明。</p><p>本课不写 HTTP 429 的全部头。也不写电力断路器物理课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把自适应并发控制（TCP Vegas、CoDel、adaptive LIFO）写全，点名即可。后课默认：依赖调用有配额与熔断；429 与 5xx 分开计数。超时退避下一课处理「失败后何时再试」，否则熔断永远被重试撬开。</p><p>保险丝保护的是系统，不是这次用户请求的恰好一次。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限流：配额内才放行；熔断：下游病则短路。</li><li>429 与故障要分开，以免误打开。</li><li>桶可超卖若只在本地近似。</li><li>出处：Hystrix；令牌桶；Nygard 稳定模式。</li></ul>',10))])}const k=l(h,[["render",E]]);export{C as __pageData,k as default};
